package com.shiftnest.attendance;
import android.os.Bundle;
import android.widget.*;
import com.google.firebase.functions.FirebaseFunctions;
import java.util.*;

/** Admin-only server endpoints; no credentials or data export is exposed to employees. */
public class StorageHealthActivity extends ShiftNestBaseActivity {
    private EditText budget,percent;private TextView status;private Button save,check,refresh;private boolean busy;
    @Override protected void onCreate(Bundle state){super.onCreate(state);if(isFinishing())return;if(!"admin".equals(role())){problem("Admin access required.");finish();return;}page("Data retention / Storage budget");
        screen.addView(text("Attendance records have no automatic deletion in this app. Storage checks estimate application document payloads; indexes, backups and cloud overhead are excluded. Your budget is a warning target, not Firebase free space. Keep private backups and verify actual Usage/Billing with the project owner.",16));
        budget=new EditText(this);budget.setHint("Data warning budget (MiB)");budget.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);screen.addView(budget);
        percent=new EditText(this);percent.setHint("Warn at percentage (50-95)");percent.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);screen.addView(percent);
        save=button("Save data budget",this::save);check=button("Check data size now",()->call("checkStorageHealth",Collections.emptyMap(),false));refresh=button("Refresh latest check",this::refresh);screen.addView(save);screen.addView(check);screen.addView(refresh);status=text("Loading storage status...",16);screen.addView(status);refresh();}
    private void buttons(){save.setEnabled(!busy);check.setEnabled(!busy);refresh.setEnabled(!busy);budget.setEnabled(!busy);percent.setEnabled(!busy);}
    private void save(){try{long mib=Long.parseLong(budget.getText().toString().trim());int warn=Integer.parseInt(percent.getText().toString().trim());if(mib<1||mib>1000000000L||warn<50||warn>95)throw new NumberFormatException();Map<String,Object> data=new HashMap<>();data.put("budgetMiB",mib);data.put("warnPercent",warn);call("saveStorageBudget",data,true);}catch(NumberFormatException e){problem("Enter a budget in MiB (1-1000000000) and warning percent (50-95).");}}
    private void refresh(){call("getStorageHealth",Collections.emptyMap(),false);}
    private void call(String name,Map<String,Object> data,boolean saved){if(busy||!requireOnline("Storage check"))return;busy=true;buttons();status.setText(name.equals("checkStorageHealth")?"Checking data size... This may take several minutes.":"Loading...");FirebaseFunctions.getInstance("asia-south1").getHttpsCallable(name).withTimeout(name.equals("checkStorageHealth")?540:30,java.util.concurrent.TimeUnit.SECONDS).call(data)
        .addOnSuccessListener(r->{if(isFinishing()||isDestroyed())return;busy=false;buttons();if(saved){success("Data budget saved. Run Check data size now to update the warning status.");refresh();return;}if(!(r.getData() instanceof Map)){status.setText("Invalid storage response. Refresh to retry.");return;}Map<?,?> raw=(Map<?,?>)r.getData();Object cfg=raw.get("budget");if(cfg instanceof Map){budget.setText(String.valueOf(((Map<?,?>)cfg).get("budgetMiB")));percent.setText(String.valueOf(((Map<?,?>)cfg).get("warnPercent")));}Object value=raw.containsKey("status")?raw.get("status"):raw;if(!(value instanceof Map)){status.setText("No check yet. Save a budget, then Check data size now.");return;}Map<?,?> m=(Map<?,?>)value;Object bytes=m.get("estimatedBytes");String amount=bytes instanceof Number?String.format(Locale.US,"%.1f MiB",((Number)bytes).doubleValue()/1048576.0):"Unknown";status.setText("State: "+m.get("state")+"\nEstimated application data: "+amount+"\nDocuments scanned: "+m.get("documents")+"\nLast check: "+m.get("checkedAt")+"\n"+(Boolean.TRUE.equals(m.get("complete"))?"Completed scan; cloud free space is not measured.":"Incomplete / unavailable; do not assume space is available.")+"\nNext: verify Firebase Usage/Billing, export a private backup and review the budget with the project owner. Never delete attendance just to clear an alert.");})
        .addOnFailureListener(e->{if(isFinishing()||isDestroyed())return;busy=false;buttons();status.setText(backendError("Storage check",e)+"\nRefresh later; a timed-out scan may still finish.");});}
}
